f=E/'slope/element.css';f.write_text(f.read_text()+'\n'+s+'\n');f=E/'slope/element.json';m=json.loads(f.read_text());m['tokenDefaults'].update({'--crossrail-pair-a':'--crossrail-s1a','--crossrail-pair-b':'--crossrail-s1b'});f.write_text(json.dumps(m,indent=2)+'\n')
